function makeEqual(words) {
  const counts = new Array(26).fill(0);
  for (const word of words) {
    for (const ch of word) {
      counts[ch.charCodeAt(0) - 97]++;
    }
  }
  for (const count of counts) {
    if (count % words.length !== 0) {
      return false;
    }
  }
  return true;
}

