function makeEqual(words) {
  // Sort every character together; each run of equal letters must split evenly across the words.
  const all = words.join('').split('').sort();
  let start = 0;
  while (start < all.length) {
    let end = start;
    while (end < all.length && all[end] === all[start]) end++;
    if ((end - start) % words.length !== 0) return false;
    start = end;
  }
  return true;
}

