function generate(rand, size) {
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 4);
  const alphabet = size === 'large' ? 26 : 1 + Math.floor(rand() * 4);
  const letter = () => String.fromCharCode(97 + Math.floor(rand() * alphabet));
  const maxWord = size === 'large' ? 100 : 5;
  const targetLength = 1 + Math.floor(rand() * maxWord);
  const target = Array.from({ length: targetLength }, letter);
  // Pool n copies of one target word, shuffle, then cut it into n pieces of 1..maxWord letters.
  const pool = [];
  for (let k = 0; k < n; k++) pool.push(...target);
  for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const lengths = new Array(n).fill(1);
  let rest = pool.length - n;
  while (rest > 0) {
    const k = Math.floor(rand() * n);
    if (lengths[k] < maxWord) { lengths[k]++; rest--; }
  }
  const words = [];
  let at = 0;
  for (const len of lengths) { words.push(pool.slice(at, at + len).join('')); at += len; }
  // About half the time, change one letter so the counts usually stop dividing evenly.
  if (rand() < 0.5) {
    const k = Math.floor(rand() * n);
    const pos = Math.floor(rand() * words[k].length);
    words[k] = words[k].slice(0, pos) + letter() + words[k].slice(pos + 1);
  }
  return [words];
}
